'use client';

import { useState, useEffect } from 'react';
import { Plus, Trash2, Globe, ExternalLink, AlertCircle, X, Loader2 } from 'lucide-react';

interface Sponsor {
  id: number;
  name: string;
  image_url: string;
  website_url: string;
}

export default function AdminSponsors() {
  const [sponsors, setSponsors] = useState<Sponsor[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [error, setError] = useState('');
  const [formData, setFormData] = useState({ name: '', image_url: '', website_url: '' });
  const [loading, setLoading] = useState(true);

  const fetchSponsors = async () => {
    try {
      const res = await fetch('http://localhost:5001/api/sponsors', { credentials: 'include' });
      const data = await res.json();
      setSponsors(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Failed to fetch:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchSponsors(); }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!formData.name.trim() || !formData.image_url.trim() || !formData.website_url.trim()) {
      setError('All fields are required to add a sponsor.');
      return;
    }

    try {
      const res = await fetch('http://localhost:5001/api/sponsors', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (res.ok) {
        setFormData({ name: '', image_url: '', website_url: '' });
        setIsModalOpen(false);
        fetchSponsors();
      }
    } catch (err) {
      setError('Server error. Please try again.');
    }
  };

  const deleteSponsor = async (id: number) => {
    if (!confirm('Are you sure you want to remove this sponsor?')) return;
    await fetch(`http://localhost:5001/api/sponsors/${id}`, { 
      method: 'DELETE',
      credentials: 'include' 
    });
    fetchSponsors();
  };

  return (
    <div className="min-h-screen bg-[#fcfcfc] p-8 md:p-12">
      <div className="max-w-6xl mx-auto">
        
        {/* Header Section */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div>
            <h1 className="text-5xl font-black uppercase italic tracking-tighter text-gray-900">
              Partner <span className="text-red-600">Hub</span>
            </h1>
            <p className="text-gray-400 text-xs font-black uppercase tracking-[0.3em] mt-2">
              Website Footer Sponsorship Control
            </p>
          </div>
          
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center justify-center gap-3 bg-red-600 text-white px-8 py-4 rounded-2xl font-black uppercase text-xs italic tracking-widest hover:bg-black transition-all shadow-xl shadow-red-600/20"
          >
            <Plus size={18} /> Add New Partner
          </button>
        </div>

        {/* Table View */}
        <div className="bg-white rounded-[2rem] shadow-xl shadow-black/5 border border-gray-100 overflow-hidden">
          <div className="px-10 py-8 border-b border-gray-50 flex justify-between items-center bg-gray-50/30">
            <h2 className="font-black uppercase text-[10px] tracking-[0.3em] text-gray-400">Active Sponsors ({sponsors.length})</h2>
          </div>
          
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-[10px] uppercase font-black text-gray-400 tracking-widest border-b border-gray-50 bg-gray-50/20">
                  <th className="px-10 py-5">Asset</th>
                  <th className="px-10 py-5">Entity Name</th>
                  <th className="px-10 py-5 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {loading ? (
                  <tr>
                    <td colSpan={3} className="py-20 text-center">
                      <Loader2 className="animate-spin mx-auto text-red-600" size={32} />
                    </td>
                  </tr>
                ) : sponsors.map((s) => (
                  <tr key={s.id} className="hover:bg-red-50/20 transition-colors group">
                    <td className="px-10 py-6">
                      <div className="w-20 h-12 bg-white border border-gray-100 rounded-xl flex items-center justify-center p-2 shadow-sm">
                        <img src={s.image_url} alt={s.name} className="max-w-full max-h-full object-contain grayscale group-hover:grayscale-0 transition-all" />
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex flex-col">
                        <span className="font-black text-gray-900 uppercase italic text-base">{s.name}</span>
                        <a href={s.website_url} target="_blank" className="text-[10px] font-bold text-red-600 hover:underline flex items-center gap-1 uppercase tracking-widest">
                          {s.website_url.replace('https://', '')} <ExternalLink size={10} />
                        </a>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-right">
                      <button 
                        onClick={() => deleteSponsor(s.id)}
                        className="w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-300 hover:bg-red-50 hover:text-red-600 transition-all"
                      >
                        <Trash2 size={18} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-lg rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="bg-red-600 p-10 text-white">
              <h3 className="text-3xl font-black uppercase italic tracking-tighter">New <span className="text-black">Partner</span></h3>
              <p className="text-[10px] text-red-200 uppercase tracking-widest font-black mt-2">Add to Website Footer</p>
            </div>

            <form onSubmit={handleSubmit} className="p-10 space-y-6">
              {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-2xl flex items-center gap-3 text-[10px] font-black uppercase border border-red-100">
                  <AlertCircle size={16} /> {error}
                </div>
              )}

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Company Name</label>
                <input 
                  type="text"
                  placeholder="ADIDAS" 
                  className="w-full bg-gray-50 border-none p-5 rounded-2xl outline-none focus:ring-2 ring-red-600 transition-all font-black uppercase text-sm italic" 
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Logo URL</label>
                <input 
                  type="text" 
                  className="w-full bg-gray-50 border-none p-5 rounded-2xl outline-none focus:ring-2 ring-red-600 transition-all font-medium text-sm" 
                  value={formData.image_url} 
                  onChange={e => setFormData({...formData, image_url: e.target.value})} 
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Redirect Website</label>
                <input 
                  type="text" 
                  className="w-full bg-gray-50 border-none p-5 rounded-2xl outline-none focus:ring-2 ring-red-600 transition-all font-medium text-sm" 
                  value={formData.website_url} 
                  onChange={e => setFormData({...formData, website_url: e.target.value})} 
                />
              </div>

              <button className="w-full bg-black text-white font-black uppercase italic tracking-widest py-6 rounded-2xl hover:bg-red-600 transition-all shadow-xl mt-4">
                Deploy Partner Logo
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}